class Solution {
  public int longestPalindromeSubseq(String s) {
    int n = s.length();
    // dp[i][j][p]: longest good palindrome in s[i..j] whose outer letter differs from p (26 = no restriction)
    int[][][] dp = new int[n + 1][n + 1][27];
    for (int i = n - 1; i >= 0; i--)
      for (int j = i + 1; j < n; j++)
        for (int p = 0; p < 27; p++) {
          int c = s.charAt(i) - 'a';
          if (s.charAt(i) == s.charAt(j) && c != p) dp[i][j][p] = 2 + dp[i + 1][j - 1][c];
          else dp[i][j][p] = Math.max(dp[i + 1][j][p], dp[i][j - 1][p]);
        }
    return n == 0 ? 0 : dp[0][n - 1][26];
  }
}
